def longestInnerBorder(s):
    n = len(s)
    pi = [0] * n
    k = 0
    for i in range(1, n):
        while k and s[i] != s[k]:
            k = pi[k - 1]
        if s[i] == s[k]:
            k += 1
        pi[i] = k
    if n < 3:
        return 0
    m = max(pi[:-1])
    k = pi[-1]
    while k > m:
        k = pi[k - 1]
    return k
